gad2(){return"\u0417\u0430 \u0432\u044b\u0443\u0447\u0435\u043d\u043d\u044b\u0435 \u0441\u043b\u043e\u0432\u0430 \u0438 \u043f\u0440\u043e\u0439\u0434\u0435\u043d\u043d\u044b\u0435 \u0443\u043f\u0440\u0430\u0436\u043d\u0435\u043d\u0438\u044f \u043d\u0430\u0447\u0438\u0441\u043b\u044f\u0435\u0442\u0441\u044f \u043e\u043f\u044b\u0442. \u041d\u0430\u0431\u0435\u0440\u0438 \u043d\u0443\u0436\u043d\u043e\u0435 \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u2014 \u0438 \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u043f\u043e\u0432\u044b\u0441\u0438\u0442\u0441\u044f."},
gacZ(){return"\u041c\u043e\u043d\u0435\u0442\u044b \u0438 \u0441\u0435\u0440\u0438\u044f"},
gacY(){return"\u041c\u043e\u043d\u0435\u0442\u044b \u2014 \u043d\u0430\u0433\u0440\u0430\u0434\u0430 \u0437\u0430 \u0437\u0430\u0434\u0430\u043d\u0438\u044f \u0438 \u0443\u0440\u043e\u043a\u0438, \u043d\u0430 \u043d\u0438\u0445 \u043f\u043e\u043a\u0443\u043f\u0430\u0435\u0442\u0441\u044f \u043a\u043e\u0440\u043c. \u041e\u0433\u043e\u043d\u0451\u043a \u2014 \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0434\u043d\u0435\u0439 \u043f\u043e\u0434\u0440\u044f\u0434 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u044b \u0432\u0441\u0435 \u0437\u0430\u0434\u0430\u043d\u0438\u044f \u0434\u043d\u044f."},
gadq(){return"\u041a\u0430\u0440\u0442\u043e\u0447\u043a\u0438 \u0441\u043b\u043e\u0432"},
gadp(){return"\u041d\u0430\u0436\u043c\u0438 \u043d\u0430 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0443, \u0447\u0442\u043e\u0431\u044b \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0435\u0451. \u0421\u043c\u0430\u0445\u043d\u0438 \u0432\u043b\u0435\u0432\u043e \u2014 \xab\u0437\u043d\u0430\u044e\xbb, \u0432\u043f\u0440\u0430\u0432\u043e \u2014 \xab\u0435\u0449\u0451 \u0443\u0447\u0438\u0442\u044c\xbb. \u0417\u043d\u0430\u043a\u043e\u043c\u043e\u0435 \u0441\u043b\u043e\u0432\u043e \u0432\u0435\u0440\u043d\u0451\u0442\u0441\u044f \u0435\u0449\u0451 \u0440\u0430\u0437 \u0441 \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u0430\u043c\u0438 \u043f\u0435\u0440\u0435\u0432\u043e\u0434\u0430: \u0432\u044b\u0431\u0435\u0440\u0438 \u0432\u0435\u0440\u043d\u044b\u0439 \u0438 \u0441\u043c\u0430\u0445\u043d\u0438 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0443 \u0432\u043b\u0435\u0432\u043e \u2014 \u0441\u043b\u043e\u0432\u043e \u0432\u044b\u0443\u0447\u0435\u043d\u043e."},
gado(){return"\u0417\u0430\u0434\u0430\u043d\u0438\u044f \u0434\u043d\u044f"},
gadn(){return"\u041a\u0430\u0436\u0434\u044b\u0439 \u0434\u0435\u043d\u044c: \u0432\u044b\u0443\u0447\u0438\u0442\u044c \u043d\u043e\u0432\u044b\u0435 \u0441\u043b\u043e\u0432\u0430, \u043f\u0440\u043e\u0439\u0442\u0438 \u0443\u0440\u043e\u043a, \u043f\u043e\u043a\u043e\u0440\u043c\u0438\u0442\u044c \u043a\u043e\u0442\u0438\u043a\u0430, \u043f\u043e\u0438\u0433\u0440\u0430\u0442\u044c \u0441 \u043d\u0438\u043c \u0438 \u0440\u0430\u0441\u0447\u0435\u0441\u0430\u0442\u044c \u0435\u0433\u043e. \u0417\u0430 \u043a\u0430\u0436\u0434\u043e\u0435 \u0437\u0430\u0434\u0430\u043d\u0438\u0435 \u2014 \u043c\u043e\u043d\u0435\u0442\u044b, \u0430 \u043d\u0430\u0436\u0430\u0442\u0438\u0435 \u043d\u0430 \u0437\u0430\u0434\u0430\u043d\u0438\u0435 \u0441\u0440\u0430\u0437\u0443 \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0435\u0433\u043e."},
gadi(){return"\u0422\u0432\u043e\u0439 \u043f\u0440\u043e\u0444\u0438\u043b\u044c"},
gadh(){return"\u041d\u0430\u0436\u043c\u0438 \u043d\u0430 \u0430\u0432\u0430\u0442\u0430\u0440, \u0447\u0442\u043e\u0431\u044b \u043e\u0442\u043a\u0440\u044b\u0442\u044c \u043f\u0440\u043e\u0444\u0438\u043b\u044c: \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430, \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u044f \u0438 \u0432\u0441\u0435 \u0432\u044b\u0443\u0447\u0435\u043d\u043d\u044b\u0435 \u0441\u043b\u043e\u0432\u0430 \u0434\u043b\u044f \u043f\u043e\u0432\u0442\u043e\u0440\u0435\u043d\u0438\u044f. \u0417\u0434\u0435\u0441\u044c \u0436\u0435 \u043c\u043e\u0436\u043d\u043e \u0432\u043e\u0439\u0442\u0438 \u0432 \u0430\u043a\u043a\u0430\u0443\u043d\u0442, \u0447\u0442\u043e\u0431\u044b \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441 \u043d\u0435 \u043f\u043e\u0442\u0435\u0440\u044f\u043b\u0441\u044f."},
gadm(){return"\u041d\u0430\u0436\u043c\u0438 \u043d\u0430 \u043f\u043e\u0434\u0441\u0432\u0435\u0447\u0435\u043d\u043d\u043e\u0435"},
