gadg(){return"\u0412\u043a\u043b\u0430\u0434\u043a\u0430 \xab\u0421\u043b\u043e\u0432\u0430\xbb"},
gadf(){return"\u0417\u0434\u0435\u0441\u044c \u0443\u0447\u0430\u0442 \u043d\u043e\u0432\u044b\u0435 \u0441\u043b\u043e\u0432\u0430. \u041e\u0442\u043a\u0440\u043e\u0439 \u0432\u043a\u043b\u0430\u0434\u043a\u0443 \u2014 \u043d\u0430\u0436\u043c\u0438 \u043d\u0430 \u043d\u0435\u0451."},
gacV(){return"\u0422\u0435\u043c\u044b \u0438 \u0443\u0440\u043e\u0432\u043d\u0438"},
gacU(){return"\u0421\u043b\u043e\u0432\u0430 \u0440\u0430\u0437\u0431\u0438\u0442\u044b \u043f\u043e \u0442\u0435\u043c\u0430\u043c, \u0430 \u0441\u0432\u0435\u0440\u0445\u0443 \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u2014 \u043e\u0442 A1 \u0434\u043e C1. \u041a\u043e\u043b\u044c\u0446\u043e \u0432\u043e\u043a\u0440\u0443\u0433 \u043a\u043d\u043e\u043f\u043a\u0438 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0441\u043b\u043e\u0432 \u0442\u0435\u043c\u044b \u0443\u0436\u0435 \u0432\u044b\u0443\u0447\u0435\u043d\u043e. \u041d\u0430\u0436\u043c\u0438 \u043d\u0430 \u043a\u0440\u0443\u0433\u043b\u0443\u044e \u043a\u043d\u043e\u043f\u043a\u0443, \u0447\u0442\u043e\u0431\u044b \u043d\u0430\u0447\u0430\u0442\u044c."},
